WITH scored AS (SELECT *, NTILE(5) OVER (PARTITION BY supplier_id ORDER BY price DESC, id) price_bucket, NTILE(4) OVER (PARTITION BY category ORDER BY stock_qty, id) stock_qty_bucket, CORR(stock_qty, price) OVER (PARTITION BY brand) corr_stock_qty_price, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY stock_qty, id) row_seq, ROW_NUMBER() OVER (ORDER BY price DESC, id) event_seq FROM products) SELECT id, category, price, stock_qty, launch_date, tags, price_bucket, stock_qty_bucket, corr_stock_qty_price FROM scored;
